import requests
import json

headers = {'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36', 'Content-Type': 'application/json'}

# Search within MrBeast's channel
payload = {
    'context': {'client': {'clientName': 'WEB', 'clientVersion': '2.20240101.00.00'}},
    'query': '',
    'params': 'EgZAZAE%3D',
    'browseId': 'UCX6OQ3DkcsbYNE6H8uQQuVA'
}
resp = requests.post('https://www.youtube.com/youtubei/v1/search', json=payload, headers=headers)
data = resp.json()

# Navigate structure
def find_videos_in(obj, depth=0):
    results = []
    if depth > 30:
        return results
    if isinstance(obj, dict):
        if 'videoRenderer' in obj:
            vr = obj['videoRenderer']
            vid = vr.get('videoId', '')
            title_raw = vr.get('title', {}).get('runs', [])
            title = ' '.join(r.get('text', '') for r in title_raw)
            length = vr.get('lengthText', {}).get('simpleText', '')
            pub = vr.get('publishedTimeText', '')
            results.append((vid, title[:60], length, pub))
        for v in obj.values():
            results.extend(find_videos_in(v, depth+1))
    elif isinstance(obj, list):
        for item in obj:
            results.extend(find_videos_in(item, depth+1))
    return results

videos = find_videos_in(data)
print(f"Found {len(videos)} videos")
for v in videos[:5]:
    print(f"  {v}")

# Look for continuations
print("\n--- Continuation items ---")
def find_continuations(obj, depth=0):
    results = []
    if depth > 25:
        return results
    if isinstance(obj, dict):
        if 'continuationItemRenderer' in obj:
            results.append(obj['continuationItemRenderer'])
        for v in obj.values():
            results.extend(find_continuations(v, depth+1))
    elif isinstance(obj, list):
        for item in obj:
            results.extend(find_continuations(item, depth+1))
    return results

conts = find_continuations(data)
print(f"Found {len(conts)} continuation items")
for c in conts[:3]:
    print(json.dumps(c, indent=2)[:300])
